const vNsByTag = `-- name: VNsByTag :many
SELECT vid, rating
  FROM tags_vn_inherit
 WHERE tag = $3::int AND rating >= $4::real
 ORDER BY rating DESC
 LIMIT $1 OFFSET $2
`

type VNsByTagParams struct {
	Limit     int32   `db:"limit" json:"limit"`
	Offset    int32   `db:"offset" json:"offset"`
	Tag       int32   `db:"tag" json:"tag"`
	MinRating float32 `db:"min_rating" json:"min_rating"`
}

type VNsByTagRow struct {
	Vid    int32   `db:"vid" json:"vid"`
	Rating float32 `db:"rating" json:"rating"`
}

// tags_vn_inherit already carries a row for every ancestor tag, so matching on
// it is the parent expansion; no closure join is needed.
func (q *Queries) VNsByTag(ctx context.Context, arg VNsByTagParams) ([]VNsByTagRow, error) {
	rows, err := q.db.Query(ctx, vNsByTag,
		arg.Limit,
		arg.Offset,
		arg.Tag,
		arg.MinRating,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VNsByTagRow{}
	for rows.Next() {
		var i VNsByTagRow
		if err := rows.Scan(&i.Vid, &i.Rating); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
